using Cont = std::function<void()>;  // reactor 스레드에서 실행될 후속
using Job  = std::function<Cont()>;  // 워커 스레드에서 실행될 블로킹 작업

struct Task {
    Job                job;
    Cont               failure;
    Cont               result;
    std::exception_ptr error;
};

std::mutex                    mu_;
std::condition_variable       cv_;
std::list<Task>               jobs_;   // 대기 job (제출 순서)
std::list<Task>               done_;   // 배출 대기 완료 노드
std::size_t                   outstanding_ = 0;
std::size_t                   capacity_;
bool                          stopping_    = false;
std::function<void()>         wake_;
std::atomic<std::size_t>      wake_errors_{0};
std::vector<std::thread>      workers_;

Offload(std::size_t threads, std::function<void()> wake, std::size_t capacity = 1024)
    : capacity_(capacity), wake_(std::move(wake))
{
    if (capacity_ == 0) throw std::invalid_argument("Offload: capacity must be > 0");
    if (threads == 0) threads = 1;
    workers_.reserve(threads);
    try {
        for (std::size_t i = 0; i < threads; ++i)
            workers_.emplace_back([this] { run(); });
    } catch (...) {
        shutdown();   // 이미 시작한 워커를 조인한 뒤 예외 전파
        throw;
    }
}

~Offload() { shutdown(); }  // completion 콜백은 호출하지 않음

Offload(const Offload&)            = delete;
Offload& operator=(const Offload&) = delete;

bool submit(Job job, Cont failure = {}) {
    if (!job) return false;
    Task task{std::move(job), std::move(failure), {}, {}};
    {
        std::lock_guard<std::mutex> lk(mu_);
        if (stopping_ || outstanding_ >= capacity_) return false;
        jobs_.push_back(std::move(task));
        ++outstanding_; // 노드 할당 성공 뒤 수락한 슬롯으로 센다.
    }
    cv_.notify_one();
    return true;
}

void run() {
    std::list<Task> running;      // 로컬 리스트 — splice 로 노드만 이동(할당 없음)
    for (;;) {
        {
            std::unique_lock<std::mutex> lk(mu_);
            cv_.wait(lk, [this] { return stopping_ || !jobs_.empty(); });
            if (jobs_.empty()) {
                if (stopping_) return;
                continue;
            }
            running.splice(running.end(), jobs_, jobs_.begin());
        }

Task& t = running.back();
try {
    t.result = t.job();   // 잠금 밖에서 블로킹 실행
} catch (...) {
    t.error = std::current_exception();
}
t.job = nullptr;          // 잠금 밖에서 job 해제

const bool publish = static_cast<bool>(t.result) || static_cast<bool>(t.error);
bool wake = false;
{
    std::lock_guard<std::mutex> lk(mu_);
    if (publish) {
        done_.splice(done_.end(), running, running.begin());
        wake = true;
    } else {
        --outstanding_; // 빈 성공은 전달할 결과가 없어 즉시 슬롯 반환
    }
}
running.clear(); // 빈 성공의 failure 캡처도 잠금 밖에서 파괴한다.
if (wake && wake_) {      // 잠금 밖에서 wake 호출
    try {
        wake_();
    } catch (...) {
        wake_errors_.fetch_add(1, std::memory_order_relaxed);
    }
}

std::size_t take_wake_errors() noexcept {
    return wake_errors_.exchange(0, std::memory_order_relaxed);
}

std::size_t drain(std::vector<Cont>& out) {
    std::list<Task> retired; // lock보다 먼저 선언: 캡처 소멸은 잠금 해제 후.
    std::lock_guard<std::mutex> lk(mu_);
    const std::size_t n = done_.size();
    if (n == 0) return 0;

    if (n > out.max_size() - out.size())
        throw std::length_error("Offload::drain: vector capacity overflow");
    out.reserve(out.size() + n);  // 이동 전에 확보 — 실패하면 done_ 유지

    std::size_t moved = 0;
    while (!done_.empty()) {
        Task& t = done_.front();
        if (t.error) {
            if (t.failure) {
                out.push_back(std::move(t.failure));
            } else {
                // 기본 처리: 루프가 이 Cont 를 호출할 때 예외를 다시 던진다
                Cont rethrow = [err = t.error] { std::rethrow_exception(err); };
                out.push_back(std::move(rethrow));
            }
        } else {
            out.push_back(std::move(t.result));
        }
        retired.splice(retired.end(), done_, done_.begin()); // 전달 성공 뒤 회수
        --outstanding_;
        ++moved;
    }
    return moved;
}

const auto id = event.id; // ID and request value cross the worker boundary.
const int request = 7;
require(pool.submit([&, id, request] {
    const int answer = request * 2;
    return [&, id, answer] {
        if (!loop.current(id)) return;
        require(answer == 14, "owned result");
        applied = true;
        require(loop.close(id), "close fast");
    };
}), "submit fast");

require(pool.submit([&, id, release] {
    entered.set_value();
    release.wait(); // Controlled blocking dependency, not event-loop work.
    const int answer = 21;
    return [&, id, answer] {
        if (!loop.current(id)) {
            discarded = true;
            std::puts("RESULT: removed registration; late answer discarded");
            return;
        }
        require(answer == 21, "slow result");
    };
}), "submit slow");

std::vector<Offload::Cont> completed;
std::vector<TimerHeap::Token> due;
const auto stop = TimerHeap::Clock::now() + 2s;
while (!(received && timed_out && discarded && applied) && TimerHeap::Clock::now() < stop) {
    const int next = timers.timeout_ms(TimerHeap::Clock::now());
    const auto batch = loop.observe(next < 0 ? 50 : std::min(next, 50));
    require(batch.state != PollState::error, "poll");
    completed.clear(); pool.drain(completed);
    for (auto& cont : completed) cont(); // Loop owns state updates.
    loop.dispatch(batch); // A completion may have removed an ID from this batch.
    due.clear(); timers.expired(TimerHeap::Clock::now(), due);
    for (const auto token : due) {
        if (!loop.current(token)) continue;
        require(loop.close(token), "timeout closes slow");
        timed_out = true;
        service.finish(); // Let the already running service return a late result.
        std::puts("TIMER: slow connection removed before worker result returns");
    }
}

void shutdown() {
    {
        std::lock_guard<std::mutex> lk(mu_);
        if (stopping_) return;
        stopping_ = true;
    }
    cv_.notify_all();
    for (auto& t : workers_) if (t.joinable()) t.join();
    workers_.clear();
}

service.finish(); pool.shutdown();
completed.clear(); pool.drain(completed);
for (auto& cont : completed) cont();

require(pool.submit([&] { return [&] { applied.push_back(2); }; }), "queued accepted");
require(!pool.submit([] { return Offload::Cont{}; }), "waiting+running capacity");
release.open(); wakes.wait(2);
require(!pool.submit([] { return Offload::Cont{}; }), "completed but undrained still holds capacity");
require(applied.empty(), "worker never runs continuation");
std::vector<Offload::Cont> out{[&] { applied.push_back(0); }};
require(pool.drain(out) == 2 && out.size() == 3, "drain appends");
for (auto& cont : out) cont();
out.clear();
require(worker_is_other && applied == std::vector<int>({0, 1, 2}), "execution ownership");
